  if(ch.length!==1) return;
  const ok=ch===want; if(!ok) t.errors++;
  const sp=document.getElementById('ty-c'+t.pos);
  if(sp){ sp.style.color=ok?'var(--good,#1f9d57)':'#fff'; sp.style.background=ok?'none':'#E0483C'; sp.style.borderRadius='3px'; }
  t.pos++; t.typed++;
