  const LC=(y)=>{ y=y||3; return y<=1?['#35B6E8','#1E8FC4']:y===2?['#6C7CF0','#4F5CD8']:y===3?['#9B5CF0','#7C3FD8']:y===4?['#E45CB0','#C43A92']:y===5?['#F0913C','#D4711C']:['#E8503E','#C43222']; };
